update public.event_cases set allowed_roles=ARRAY['глава','министр транспорта','министр здравоохранения']::text[],effect_plan='{"options": [{"key": "option_1", "trust": 2, "description": "Дежурный медик определяет очерёдность, а подвоз топлива восстанавливает сообщения. Обычные поездки придётся отложить.", "public_interest": "beneficial", "news": "Дежурный медик определяет очерёдность, а подвоз топлива восстанавливает сообщения. Обычные поездки придётся отложить.", "authorized_roles": ["глава", "министр транспорта", "министр здравоохранения"], "lawful": true, "protects_role_interest": true, "legal_basis": "Учебная разметка конкретной ситуации: компетенция глава, министр транспорта, министр здравоохранения. Конституция РФ, статьи 15, 71–73, 114, 130–132. Последствия и границы компетенции проверяет преподаватель."}, {"key": "option_2", "trust": 0, "description": "Объезд снижает риск аварии, но помощь прибывает позднее. Жителям нужен отдельный канал срочных обращений.", "public_interest": "neutral", "news": "Объезд снижает риск аварии, но помощь прибывает позднее. Жителям нужен отдельный канал срочных обращений.", "authorized_roles": ["глава", "министр транспорта", "министр здравоохранения"], "lawful": true, "protects_role_interest": false, "legal_basis": "Учебная разметка конкретной ситуации: компетенция глава, министр транспорта, министр здравоохранения. Конституция РФ, статьи 15, 71–73, 114, 130–132. Последствия и границы компетенции проверяет преподаватель."}, {"key": "option_3", "trust": -2, "description": "Очередь сокращается, однако неподтверждённая безопасность переправы создаёт новый риск и подрывает доверие.", "public_interest": "harmful", "news": "Очередь сокращается, однако неподтверждённая безопасность переправы создаёт новый риск и подрывает доверие.", "authorized_roles": ["глава", "министр транспорта", "министр здравоохранения"], "lawful": false, "protects_role_interest": false, "legal_basis": "Учебная разметка конкретной ситуации: компетенция глава, министр транспорта, министр здравоохранения. Конституция РФ, статьи 15, 71–73, 114, 130–132. Последствия и границы компетенции проверяет преподаватель."}, {"key": "option_4", "trust": 1, "description": "Часть помощи оказывается на месте. Сложные случаи всё ещё требуют переправы, поэтому временный пункт дополняет, а не заменяет транспорт.", "public_interest": "beneficial", "news": "Часть помощи оказывается на месте. Сложные случаи всё ещё требуют переправы, поэтому временный пункт дополняет, а не заменяет транспорт.", "authorized_roles": ["глава", "министр транспорта", "министр здравоохранения"], "lawful": true, "protects_role_interest": true, "legal_basis": "Учебная разметка конкретной ситуации: компетенция глава, министр транспорта, министр здравоохранения. Конституция РФ, статьи 15, 71–73, 114, 130–132. Последствия и границы компетенции проверяет преподаватель."}, {"key": "option_5", "trust": -2, "description": "Платёжеспособность подменяет медицинскую срочность. Люди с наибольшей потребностью могут остаться без рейса.", "public_interest": "harmful", "news": "Платёжеспособность подменяет медицинскую срочность. Люди с наибольшей потребностью могут остаться без рейса.", "authorized_roles": ["глава", "министр транспорта", "министр здравоохранения"], "lawful": false, "protects_role_interest": false, "legal_basis": "Учебная разметка конкретной ситуации: компетенция глава, министр транспорта, министр здравоохранения. Конституция РФ, статьи 15, 71–73, 114, 130–132. Последствия и границы компетенции проверяет преподаватель."}]}'::jsonb where case_key='bank-curated-v2-01' and not exists(select 1 from public.event_case_outcomes where case_id=event_cases.id);
